SELECT COUNT(1)
FROM bt_dc_document_activity
WHERE document_id = #{documentId}
AND action_type = #{actionType}
AND status_cd = '00A'

  AND created_time >= #{startTime}


  AND created_time <= #{endTime}

SELECT COUNT(1)
FROM bt_dc_document_activity
WHERE status_cd = '00A'

  AND document_id = #{documentId}


  AND library_id = #{libraryId}


  AND user_id = #{userId}


  AND action_type = #{actionType}


  AND created_time >= #{startTime}


  AND created_time <= #{endTime}

SELECT bdda.activity_id, bdda.document_id, bdda.library_id, bdda.user_id, bdda.action_type, bdda.ip_address, bdda.user_agent, bdda.creator_id, bdda.created_time, bdda.status_cd, bdda.tenant_id, bdd.document_name, bdd.document_type, bddl.library_name, bdda.old_document_name, bdda.target_library_id, bddlt.library_name as target_library_name, case when bdd.status_cd = '00A' then 0 else 1 end as document_deleted, case when bddlt.status_cd = '00A' then 0 else 1 end as target_library_deleted FROM bt_dc_document_activity bdda left join bt_dc_document bdd on bdd.document_id = bdda.document_id left join bt_dc_document_library bddl on bddl.library_id = bdda.library_id and bddl.status_cd = '00A' left join bt_dc_document_library bddlt on bddlt.library_id = bdda.target_library_id WHERE bdda.status_cd = '00A'
AND bdda.document_id = #{queryParams.documentId}
AND bdda.library_id = #{queryParams.libraryId}
AND bdda.user_id = #{queryParams.userId}
AND bdda.action_type = #{queryParams.actionType}
AND bdda.action_type != 'VIEW'
AND bdda.created_time >= #{queryParams.startTime}
AND bdda.created_time <= #{queryParams.endTime}
AND bdda.tenant_id = #{queryParams.tenantId}
ORDER BY bdda.created_time DESC

SELECT DISTINCT document_id
FROM bt_dc_document_activity
WHERE status_cd = '00A'
  AND created_time >= #{startTime}
  AND created_time < #{endTime}
